-- ---------------------------------------------------------------------------
-- Dashboard screens for the mobile/wall UI (/wui).
--
-- Two floor plans of the fictional demo house, each with widgets bound to the
-- peripherals seeded by demo-entities.sql. Coordinates are in the background
-- image's own pixel space (1280x800), which is what DashboardScreenSvg uses as
-- its viewBox - so they stay correct at any display size.
--
-- Separate from demo-entities.sql only because of the image bytes: keeping the
-- base64 here leaves that file readable. It must run after it, and before
-- demo-seed-schema.sql takes its snapshot.
--
-- The images are embedded rather than read from disk because this SQL is
-- executed by the postgres container's init directory, which receives only the
-- .sql files - a file path here would resolve inside the database container.
-- ---------------------------------------------------------------------------

\set ON_ERROR_STOP on

-- The application connects with TimeZone=UTC, so every timestamp it writes is
-- UTC. psql inherits the server's zone instead, which would store these rows in
-- local wall time - three hours in the future on a UTC+3 host, which the UI then
-- renders as messages that arrive later today. Match the application.
SET timezone = 'UTC';
INSERT INTO dashboard_screens (id, version, name, ordinal, enabled, layout_json,
                               background_content_type, background_width, background_height,
                               ts_created, ts_updated, en_type)
VALUES
