-- Fail loudly here rather than serving a truncated image to the viewer.
DO $$
DECLARE
    n int;
BEGIN
    SELECT count(*) INTO n FROM dashboard_screen_backgrounds
     WHERE (id = 7311 AND octet_length(data) = 93002)
        OR (id = 7312 AND octet_length(data) = 105581);
    IF n <> 2 THEN
        RAISE EXCEPTION 'dashboard screen backgrounds did not decode to their original size';
    END IF;
END
$$;
